int vec_reserve_po2_( char **data, int *length, int *capacity, int memsz, int n )
{
    int n2 = 1;
    if ( n == 0 ) {
        return 0;
    }
    while ( n2 < n ) {
        n2 *= 2;
    }
    return vec_reserve_( data, length, capacity, memsz, n2 );
