int vec_insert_(char **data, int *length, int *capacity, int memsz, int idx)
{
    int ret = vec_expand_(data, length, capacity, memsz);
    if (ret != 0) {
        return ret;
    }

    char *base = *data;
    memmove(base + (size_t)(idx + 1) * (size_t)memsz,
            base + (size_t)idx * (size_t)memsz,
            (size_t)(*length - idx - 1) * (size_t)memsz);

    return 0;
}
