```c
static inline char sdsReqType(size_t string_size) {
    if (string_size < 32)
        return SDS_TYPE_5;
    if (string_size < 256)
        return SDS_TYPE_8;
    if (string_size < 65536)
        return SDS_TYPE_16;
    if (sizeof(long) >= 8) {
        if (string_size < 4294967296ULL)
            return SDS_TYPE_32;
        return SDS_TYPE_64;
    } else {
        return SDS_TYPE_32;
    }
}
