sds sdsnewlen(const void *init, size_t initlen) {
    void *sh;
    sds s;
    char type = sdsReqType(initlen);
    int hdrlen;
    unsigned char flags;

    if (type == SDS_TYPE_5 && initlen == 0) type = SDS_TYPE_8;
    hdrlen = sdsHdrSize(type);
    sh = s_malloc(hdrlen + initlen + 1);
    if (sh == NULL) return NULL;

    if (init == SDS_NOINIT) {
        /* leave content uninitialized */
    } else if (init == NULL) {
        memset(sh, 0, hdrlen + initlen + 1);
    }

    s = (char *)sh + hdrlen;
    flags = (unsigned char)type;

    switch (type) {
    case SDS_TYPE_8: {
        SDS_HDR_VAR(8, s);
        sh->len = (uint8_t)initlen;
        sh->alloc = (uint8_t)initlen;
        sh->flags = flags;
        break;
    }
    case SDS_TYPE_16: {
        SDS_HDR_VAR(16, s);
        sh->len = (uint16_t)initlen;
        sh->alloc = (uint16_t)initlen;
        sh->flags = flags;
        break;
    }
    case SDS_TYPE_32: {
        SDS_HDR_VAR(32, s);
        sh->len = (uint32_t)initlen;
        sh->alloc = (uint32_t)initlen;
        sh->flags = flags;
        break;
    }
    case SDS_TYPE_64: {
        SDS_HDR_VAR(64, s);
        sh->len = (uint64_t)initlen;
        sh->alloc = (uint64_t)initlen;
        sh->flags = flags;
        break;
    }
    }

    if (initlen > 0 && init != NULL && init != SDS_NOINIT) {
        memcpy(s, init, initlen);
    }
    s[initlen] = '\0';
    return s;
}
