int sdsll2str(char *s, long long value) {
    char *p = s;
    unsigned long long v;

    if (value < 0) {
        *p++ = '-';
        v = (unsigned long long)(-(value + 1)) + 1ULL;
    } else {
        v = (unsigned long long)value;
    }

    char tmp[20];
    int len = 0;

    do {
        tmp[len++] = (char)('0' + (v % 10));
        v /= 10;
    } while (v != 0);

    while (len > 0) {
        *p++ = tmp[--len];
    }

    *p = '\0';

    return (int)(p - s);
}
```

