int sdsull2str(char *s, unsigned long long v)
{
    char buf[20];
    int len = 0;
    int i;

    if (v == 0) {
        s[0] = '0';
        s[1] = '\0';
        return 1;
    }

    while (v > 0) {
        buf[len++] = (char)('0' + (v % 10));
        v /= 10;
    }

    for (i = 0; i < len; i++) {
        s[i] = buf[len - 1 - i];
    }
    s[len] = '\0';

    return len;
}
