sds sdstrim(sds s, const char *cset) {
    char *start, *end, *sp, *ep;
    size_t len;

    if (cset == NULL || *cset == '\0') return s;

    sp = start = s;
    ep = end = s + sdslen(s) - 1;

    while (sp <= end && strchr(cset, *sp)) sp++;
    while (ep > sp && strchr(cset, *ep)) ep--;

    len = (sp > ep) ? 0 : ((ep - sp) + 1);

    if (start != sp && len > 0) {
        memmove(start, sp, len);
    }

    start[len] = '\0';
    sdssetlen(s, len);
    return s;
}
