static unsigned parse_hex4(const unsigned char * const input)
{
    unsigned h = 0;
    int i;

    for (i = 0; i < 4; i++) {
        unsigned char c = input[i];
        unsigned v;

        if (c >= '0' && c <= '9') {
            v = (unsigned)(c - '0');
        } else if (c >= 'A' && c <= 'F') {
            v = (unsigned)(c - 'A' + 10);
        } else if (c >= 'a' && c <= 'f') {
            v = (unsigned)(c - 'a' + 10);
        } else {
            return 0;
        }

        h = (h << 4) | v;
    }

    return h;
}
