static unsigned char utf16_literal_to_utf8(const unsigned char * const input_pointer, const unsigned char * const input_end, unsigned char **output_pointer)
{
    unsigned long codepoint = 0;
    unsigned first_code = 0;
    unsigned char first_byte_mark = 0;
    unsigned char sequence_length = 0;
    const unsigned char *input = input_pointer;
    unsigned char *output = *output_pointer;

    if (input_end - input < 6)
    {
        return 0;
    }

    if (input[0] != '\\' || input[1] != 'u')
    {
        return 0;
    }

    first_code = parse_hex4(input + 2);

    if (first_code >= 0xDC00 && first_code <= 0xDFFF)
    {
        return 0;
    }

    if (first_code >= 0xD800 && first_code <= 0xDBFF)
    {
        unsigned second_code = 0;

        if (input_end - input < 12)
        {
            return 0;
        }

        if (input[6] != '\\' || input[7] != 'u')
        {
            return 0;
        }

        second_code = parse_hex4(input + 8);

        if (second_code < 0xDC00 || second_code > 0xDFFF)
        {
            return 0;
        }

        codepoint = 0x10000 + (((unsigned long)(first_code - 0xD800)) << 10) + (second_code - 0xDC00);
        sequence_length = 12;
    }
    else
    {
        codepoint = first_code;
        sequence_length = 6;
    }

    if (codepoint < 0x80)
    {
        first_byte_mark = 0;
        output[0] = (unsigned char)codepoint;
        output += 1;
    }
    else if (codepoint < 0x800)
    {
        first_byte_mark = 0xC0;
        output[1] = (unsigned char)((codepoint & 0x3F) | 0x80);
        output[0] = (unsigned char)((codepoint >> 6) | first_byte_mark);
        output += 2;
    }
    else if (codepoint < 0x10000)
    {
        first_byte_mark = 0xE0;
        output[2] = (unsigned char)((codepoint & 0x3F) | 0x80);
        output[1] = (unsigned char)(((codepoint >> 6) & 0x3F) | 0x80);
        output[0] = (unsigned char)((codepoint >> 12) | first_byte_mark);
        output += 3;
    }
    else
    {
        first_byte_mark = 0xF0;
        output[3] = (unsigned char)((codepoint & 0x3F) | 0x80);
        output[2] = (unsigned char)(((codepoint >> 6) & 0x3F) | 0x80);
        output[1] = (unsigned char)(((codepoint >> 12) & 0x3F) | 0x80);
        output[0] = (unsigned char)((codepoint >> 18) | first_byte_mark);
        output += 4;
    }

    *output_pointer = output;

    return sequence_length;
}
