```c
cJSON * cJSON_Duplicate_rec(const cJSON *item, size_t depth, cJSON_bool recurse)
{
    cJSON *newitem = NULL;
    cJSON *child = NULL;
    cJSON *next = NULL;
    cJSON *newchild = NULL;

    if (item == NULL)
    {
        return NULL;
    }

    newitem = cJSON_New_Item(&global_hooks);
    if (newitem == NULL)
    {
        return NULL;
    }

    newitem->type = item->type & (~cJSON_IsReference);
    newitem->valueint = item->valueint;
    newitem->valuedouble = item->valuedouble;

    if (item->valuestring != NULL)
    {
        newitem->valuestring = (char*)cJSON_strdup((const unsigned char*)item->valuestring, &global_hooks);
        if (newitem->valuestring == NULL)
        {
            cJSON_Delete(newitem);
            return NULL;
        }
    }

    if (item->string != NULL)
    {
        if ((item->type & cJSON_StringIsConst) != 0)
        {
            newitem->string = item->string;
        }
        else
        {
            newitem->string = (char*)cJSON_strdup((const unsigned char*)item->string, &global_hooks);
            if (newitem->string == NULL)
            {
                cJSON_Delete(newitem);
                return NULL;
            }
        }
    }

    if (!recurse)
    {
        return newitem;
    }

    if (depth >= CJSON_CIRCULAR_LIMIT)
    {
        cJSON_Delete(newitem);
        return NULL;
    }

    child = item->child;
    while (child != NULL)
    {
        next = child->next;
        newchild = cJSON_Duplicate_rec(child, depth + 1, true);
        if (newchild == NULL)
        {
            cJSON_Delete(newitem);
            return NULL;
        }

        if (newitem->child == NULL)
        {
            newitem->child = newchild;
        }
        else
        {
            newchild->prev = newitem->child->prev;
            newitem->child->prev->next = newchild;
        }
        newitem->child->prev = newchild;

        child = next;
    }

    return newitem;
}
