static void minify_string(char **input, char **output)
{
    char *in = *input;
    char *out = *output;

    *out = *in;
    in++;
    out++;

    while (*in != '\0') {
        if (*in == '"') {
            *out = *in;
            out++;
            in++;
            break;
        } else if (*in == '\\' && *(in + 1) == '"') {
            *out = '"';
            out++;
            in += 2;
        } else {
            *out = *in;
            out++;
            in++;
        }
    }

    *input = in;
    *output = out;
}
