CJSON_PUBLIC(void) cJSON_Minify(char *json)
{
    char *into = json;

    if (json == NULL)
    {
        return;
    }

    while (*json != '\0')
    {
        if (*json == ' ')
        {
            json++;
        }
        else if (*json == '\t')
        {
            json++;
        }
        else if (*json == '\r')
        {
            json++;
        }
        else if (*json == '\n')
        {
            json++;
        }
        else if ((*json == '/') && (json[1] == '/'))
        {
            skip_oneline_comment(&json);
        }
        else if ((*json == '/') && (json[1] == '*'))
        {
            skip_multiline_comment(&json);
        }
        else if (*json == '\"')
        {
            minify_string(&json, &into);
        }
        else
        {
            *into = *json;
            into++;
            json++;
        }
    }

    *into = '\0';
}
