static cJSON_bool compare_pointers(const unsigned char *name, const unsigned char *pointer, const cJSON_bool case_sensitive)
{
    if (name == NULL || pointer == NULL)
    {
        return false;
    }

    while (*name != '\0' && *pointer != '\0' && *pointer != '/')
    {
        unsigned char name_char = *name;
        unsigned char pointer_char;

        if (*pointer == '~')
        {
            pointer++;
            if (*pointer == '0')
            {
                pointer_char = '~';
            }
            else if (*pointer == '1')
            {
                pointer_char = '/';
            }
            else
            {
                return false;
            }
            pointer++;
        }
        else
        {
            pointer_char = *pointer;
            pointer++;
        }

        if (case_sensitive)
        {
            if (name_char != pointer_char)
            {
                return false;
            }
        }
        else
        {
            if (tolower((int)name_char) != tolower((int)pointer_char))
            {
                return false;
            }
        }

        name++;
    }

    if (*name != '\0')
    {
        return false;
    }
    if (*pointer != '\0' && *pointer != '/')
    {
        return false;
    }

    return true;
}
