static void encode_string_as_pointer(unsigned char *destination, const unsigned char *source)
{
    while (*source != '\0') {
        if (*source == '/') {
            *destination++ = '~';
            *destination++ = '1';
        } else if (*source == '~') {
            *destination++ = '~';
            *destination++ = '0';
        } else {
            *destination++ = *source;
        }
        source++;
    }
    *destination = '\0';
}
