CJSON_PUBLIC(char *) cJSONUtils_FindPointerFromObjectTo(const cJSON * const object, const cJSON * const target)
{
    size_t child_index = 0;
    cJSON *current_child = 0;

    if ((object == NULL) || (target == NULL))
    {
        return NULL;
    }

    if (object == target)
    {
        /* found the target */
        return (char*)cJSONUtils_strdup((const unsigned char*)"");
    }

    /* recursively search all children of the object or array */
    for (current_child = object->child; current_child != NULL; (void)(current_child = current_child->next), child_index++)
    {
        unsigned char *target_pointer = (unsigned char*)cJSONUtils_FindPointerFromObjectTo(current_child, target);
        /* if the target was found */
        if (target_pointer != NULL)
        {
            size_t target_pointer_length = strlen((char*)target_pointer);
            size_t encoded_length = 0;
            unsigned char *full_pointer = NULL;
            size_t prefix_length = 0;

            if (cJSON_IsArray(object))
            {
                /* convert the index to a string */
                char index_string[21];
                size_t index_length = 0;
                size_t value = child_index;
                char reversed[21];
                size_t reversed_length = 0;

                do
                {
                    reversed[reversed_length] = (char)('0' + (value % 10));
                    reversed_length++;
                    value /= 10;
                } while (value > 0);

                while (reversed_length > 0)
                {
                    reversed_length--;
                    index_string[index_length] = reversed[reversed_length];
                    index_length++;
                }
                index_string[index_length] = '\0';

                encoded_length = index_length;
                prefix_length = 1 + encoded_length;

                full_pointer = (unsigned char*)cJSON_malloc(prefix_length + target_pointer_length + 1);
                if (full_pointer == NULL)
                {
                    cJSON_free(target_pointer);
                    return NULL;
                }

                full_pointer[0] = '/';
                memcpy(full_pointer + 1, index_string, index_length);
                memcpy(full_pointer + prefix_length, target_pointer, target_pointer_length + 1);
            }
            else if (cJSON_IsObject(object))
            {
                const unsigned char *name = (const unsigned char*)current_child->string;
                if (name == NULL)
                {
                    name = (const unsigned char*)"";
                }

                encoded_length = pointer_encoded_length(name);
                prefix_length = 1 + encoded_length;

                full_pointer = (unsigned char*)cJSON_malloc(prefix_length + target_pointer_length + 1);
                if (full_pointer == NULL)
                {
                    cJSON_free(target_pointer);
                    return NULL;
                }

                full_pointer[0] = '/';
                encode_string_as_pointer(full_pointer + 1, name);
                memcpy(full_pointer + prefix_length, target_pointer, target_pointer_length + 1);
            }
            else
            {
                /* not an array or object, but has children: free and return NULL */
                cJSON_free(target_pointer);
                return NULL;
            }

            cJSON_free(target_pointer);
            return (char*)full_pointer;
        }
    }

    return NULL;
}
