static cJSON_bool decode_array_index_from_pointer(const unsigned char * const pointer, size_t * const index)
{
    size_t parsed_index = 0;
    size_t position = 0;

    if ((pointer == NULL) || (index == NULL))
    {
        return 0;
    }

    if (pointer[0] == '\0')
    {
        return 0;
    }

    if (pointer[0] == '0')
    {
        if ((pointer[1] != '\0') && (pointer[1] != '/'))
        {
            return 0;
        }
        *index = 0;
        return 1;
    }

    while ((pointer[position] != '\0') && (pointer[position] != '/'))
    {
        if ((pointer[position] < '0') || (pointer[position] > '9'))
        {
            return 0;
        }
        parsed_index = (parsed_index * 10) + (size_t)(pointer[position] - '0');
        position++;
    }

    if (position == 0)
    {
        return 0;
    }

    *index = parsed_index;
    return 1;
}
