  unsigned int i;

  parser->pos++;

  for (i = parser->pos; i < len && js[i] != '\0'; i++) {
    char c = js[i];

    if (c == '"') {
      if (tokens == NULL) {
        parser->pos = i + 1;
        return 0;
      } else {
        jsmntok_t *token = jsmn_alloc_token(parser, tokens, num_tokens);
        if (token == NULL) {
          parser->pos = start;
          return JSMN_ERROR_NOMEM;
        }
        jsmn_fill_token(token, JSMN_STRING, (int)(start + 1), (int)i);
        parser->pos = i + 1;
        return 0;
