    } else if (c == '\\') {
      i++;
      if (i >= len || js[i] == '\0') {
        parser->pos = start;
        return JSMN_ERROR_PART;
      }
      c = js[i];
      if (c == '"' || c == '/' || c == '\\' || c == 'b' || c == 'f' ||
          c == 'r' || c == 'n' || c == 't') {
        /* valid single-character escape */
      } else if (c == 'u') {
