  i->string = (char *)malloc(len + 1);
  memcpy(i->string, string, len + 1);

  i->state = mpc_state_new();
  i->state.pos = 0;
  i->state.row = 0;
  i->state.col = 0;
  i->state.term = 0;

  i->buffer = NULL;
  i->file = NULL;

  i->suppress = 0;
  i->backtrack = 1;

  i->marks_slots = MPC_INPUT_MARKS_MIN;
  i->marks_num = 0;
  i->marks = (mpc_state_t *)malloc(sizeof(mpc_state_t) * (size_t)i->marks_slots);
  i->lasts = (char *)malloc(sizeof(char) * (size_t)i->marks_slots);

  i->last = '\0';

  i->mem_index = 0;
  memset(i->mem_full, 0, sizeof(char) * MPC_INPUT_MEM_NUM);

  return i;
}
