```c
static void mpc_input_unmark(mpc_input_t *i) {
  int new_slots;
  int min_slots;
  mpc_state_t *new_marks;
  char *new_lasts;

  if (i->marks_num < 1) {
    return;
  }

  i->marks_num--;

  new_slots = i->marks_num;
  min_slots = MPC_INPUT_MARKS_MIN;

  if (i->marks_slots > (i->marks_num * 3) / 2 &&
      i->marks_slots > min_slots) {
    if (new_slots < min_slots) {
      new_slots = min_slots;
    }

    new_marks = realloc(i->marks, sizeof(mpc_state_t) * (size_t)new_slots);
    if (new_marks != NULL) {
      i->marks = new_marks;
    }

    new_lasts = realloc(i->lasts, sizeof(char) * (size_t)new_slots);
    if (new_lasts != NULL) {
      i->lasts = new_lasts;
    }

    i->marks_slots = new_slots;
  }

  if (i->type == MPC_INPUT_PIPE && i->marks_num == 0) {
    int j;
    for (j = (int)strlen(i->buffer) - 1; j >= 0; j--) {
      ungetc(i->buffer[j], i->file);
    }
    free(i->buffer);
    i->buffer = NULL;
  }
}
