```c
static mpc_err_t *mpc_err_or(mpc_input_t *i, mpc_err_t** x, int n) {
  int j, k, first;
  mpc_err_t *e;
  mpc_state_t s;
  long max_pos;

  first = -1;
  for (j = 0; j < n; j++) {
    if (x[j] != NULL) { first = j; }
  }

  if (first == -1) { return NULL; }

  e = mpc_malloc(i, sizeof(mpc_err_t));
  e->state = mpc_state_invalid();
  e->expected_num = 0;
  e->expected = NULL;
  e->failure = NULL;
  e->filename = mpc_malloc(i, strlen(x[first]->filename) + 1);
  strcpy(e->filename, x[first]->filename);

  max_pos = x[first]->state.pos;
  for (j = 0; j < n; j++) {
    if (x[j] != NULL && x[j]->state.pos > max_pos) {
      max_pos = x[j]->state.pos;
    }
  }

  e->state.pos = max_pos;

  for (j = 0; j < n; j++) {
    if (x[j] == NULL || x[j]->state.pos != max_pos) { continue; }

    if (x[j]->failure != NULL) {
      e->failure = mpc_malloc(i, strlen(x[j]->failure) + 1);
      strcpy(e->failure, x[j]->failure);
      break;
    }

    e->received = x[j]->received;

    for (k = 0; k < x[j]->expected_num; k++) {
      if (!mpc_err_contains_expected(i, e, x[j]->expected[k])) {
        mpc_err_add_expected(i, e, x[j]->expected[k]);
      }
    }
  }

  for (j = 0; j < n; j++) {
    if (x[j] != NULL) {
      mpc_err_delete_internal(i, x[j]);
    }
  }

  return e;
}
