static mpc_result_t *mpc_grow_results(mpc_input_t *i, int j, mpc_result_t *results_stk, mpc_result_t *results) {
  int new_capacity;
  mpc_result_t *new_results;

  new_capacity = (j * 3) / 2;

  if (j == MPC_PARSE_STACK_MIN) {
    new_results = mpc_malloc(i, (size_t)new_capacity * sizeof(mpc_result_t));
    if (new_results == NULL) {
      return NULL;
    }
    memcpy(new_results, results_stk, (size_t)MPC_PARSE_STACK_MIN * sizeof(mpc_result_t));
    return new_results;
  } else {
    new_results = mpc_realloc(i, results, (size_t)new_capacity * sizeof(mpc_result_t));
    if (new_results == NULL) {
      return NULL;
    }
    return new_results;
  }
