```c
static mpc_val_t *mpcf_re_range(mpc_val_t *x) {
  mpc_parser_t *out;
  size_t i, j, len;
  size_t start, end;
  const char *tmp = NULL;
  const char *s = (const char*)x;
  int comp = 0;
  char *buf;
  size_t buflen;
  size_t bufcap;

  len = strlen(s);

  if (len == 0 || (len == 1 && s[0] == '^')) {
    free(x);
    return mpc_fail("Invalid Regex Range Expression");
  }

  if (s[0] == '^') {
    comp = 1;
    start = 1;
  } else {
    start = 0;
  }

  bufcap = len * 4 + 1;
  buf = (char*)malloc(bufcap);
  buflen = 0;

  i = start;
  while (i < len) {
    char c = s[i];

    if (c == '\\') {
      if (i + 1 < len) {
        char e = s[i + 1];
        tmp = mpc_re_range_escape_char(e);
        if (tmp != NULL) {
          size_t tl = strlen(tmp);
          while (buflen + tl + 1 > bufcap) {
            bufcap *= 2;
            buf = (char*)realloc(buf, bufcap);
          }
          memcpy(buf + buflen, tmp, tl);
          buflen += tl;
        } else {
          if (buflen + 2 > bufcap) {
            bufcap *= 2;
            buf = (char*)realloc(buf, bufcap);
          }
          buf[buflen++] = e;
        }
        i += 2;
      } else {
        if (buflen + 2 > bufcap) {
          bufcap *= 2;
          buf = (char*)realloc(buf, bufcap);
        }
        buf[buflen++] = '\\';
        i += 1;
      }
      continue;
    }

    if (c == '-' && i > start && i + 1 < len) {
      char prev = s[i - 1];
      char next = s[i + 1];
      char ch;
      if (prev == '\\') {
        if (buflen + 2 > bufcap) {
          bufcap *= 2;
          buf = (char*)realloc(buf, bufcap);
        }
        buf[buflen++] = '-';
        i += 1;
        continue;
      }
      if (next == '\\') {
        if (buflen + 2 > bufcap) {
          bufcap *= 2;
          buf = (char*)realloc(buf, bufcap);
        }
        buf[buflen++] = '-';
        i += 1;
        continue;
      }
      if (prev <= next) {
        for (ch = prev; ; ch++) {
          if (buflen + 2 > bufcap) {
            bufcap *= 2;
            buf = (char*)realloc(buf, bufcap);
          }
          buf[buflen++] = ch;
          if (ch == next) break;
        }
      }
      i += 2;
      continue;
    }

    if (buflen + 2 > bufcap) {
      bufcap *= 2;
      buf = (char*)realloc(buf, bufcap);
    }
    buf[buflen++] = c;
    i += 1;
  }

  buf[buflen] = '\0';

  if (comp) {
    out = mpc_noneof(buf);
  } else {
    out = mpc_oneof(buf);
  }

  free(buf);
  free(x);

  (void)j;
  (void)end;
  return out;
}
