mpc_ast_t *mpc_ast_add_tag(mpc_ast_t *a, const char *t) {
  size_t t_len;
  size_t tag_len;
  char *new_tag;

  if (a == NULL) {
    return NULL;
  }

  t_len = strlen(t);
  tag_len = (a->tag != NULL) ? strlen(a->tag) : 0;

  new_tag = (char *)malloc(t_len + 1 + tag_len + 1);
  if (new_tag == NULL) {
    return NULL;
  }

  memcpy(new_tag, t, t_len);
  new_tag[t_len] = '|';
  if (a->tag != NULL) {
    memcpy(new_tag + t_len + 1, a->tag, tag_len);
  }
  new_tag[t_len + 1 + tag_len] = '\0';

  free(a->tag);
  a->tag = new_tag;

  return a;
}
