static mpc_parser_t *mpca_grammar_find_parser(char *x, mpca_grammar_st_t *st) {
  int i, n;
  mpc_parser_t *p;

  if (is_number(x)) {
    n = atoi(x);

    while (st->parsers_num <= n) {
      p = va_arg(*st->va, mpc_parser_t*);
      if (p == NULL) {
        return mpc_failf("No such parser at position %i. Only %i parsers supplied.", n, st->parsers_num);
      }
      st->parsers_num++;
      st->parsers = realloc(st->parsers, sizeof(mpc_parser_t*) * st->parsers_num);
      st->parsers[st->parsers_num - 1] = p;
    }

    return st->parsers[n];
  }

  for (i = 0; i < st->parsers_num; i++) {
    if (st->parsers[i] == NULL) {
      return mpc_failf("Unknown parser '%s'.", x);
    }
    if (st->parsers[i]->name != NULL && strcmp(st->parsers[i]->name, x) == 0) {
      return st->parsers[i];
    }
  }

  for (;;) {
    p = va_arg(*st->va, mpc_parser_t*);
    if (p == NULL || p->name == NULL) {
      return mpc_failf("Unknown parser '%s'.", x);
    }
    st->parsers_num++;
    st->parsers = realloc(st->parsers, sizeof(mpc_parser_t*) * st->parsers_num);
    st->parsers[st->parsers_num - 1] = p;
    if (strcmp(p->name, x) == 0) {
      return p;
    }
  }
}
