mpc_parser_t *mpca_grammar_st(const char *grammar, mpca_grammar_st_t *st)
{
  mpc_parser_t *p;
  mpc_result_t r;
  mpc_parser_t *base, *factor, *term, *rule, *rules, *grammar_p;
  mpc_parser_t *regex_flags, *regex_ci, *regex_ml, *regex_body;
  mpc_parser_t *count, *repeat_suffix, *factor_suffix;
  mpc_parser_t *parens, *braces, *brackets;
  mpc_parser_t *lit_str, *lit_char, *lit_regex, *lit_id;
  mpc_parser_t *term_rest, *rule_rest;

  /* String literal */
  lit_str = mpc_apply_to(mpc_string_lit(), mpcaf_grammar_string, st);

  /* Character literal */
  lit_char = mpc_apply_to(mpc_char_lit(), mpcaf_grammar_char, st);

  /* Regex flags */
  regex_ci = mpc_or(2, mpc_sym("i"), mpc_pass());
  regex_ml = mpc_or(2, mpc_sym("m"), mpc_pass());
  regex_flags = mpc_and(2, mpcf_strfold, regex_ci, regex_ml, free);

  /* Regex literal with optional flags */
  regex_body = mpc_regex_lit();
  lit_regex = mpc_and(2, mpcaf_fold_regex, regex_body, mpc_maybe(regex_flags), free);

  /* Identifier */
  lit_id = mpc_apply_to(mpc_ident(), mpcaf_grammar_id, st);

  /* Repetition count: {n} */
  count = mpc_tok_braces(mpc_int(), free);

  /* Repetition suffixes */
  repeat_suffix = mpc_or(5,
    mpc_sym("*"),
    mpc_sym("+"),
    mpc_sym("?"),
    mpc_sym("!"),
    count);

  factor_suffix = mpc_maybe(repeat_suffix);

  /* Parenthesized subexpression */
  parens = mpc_tok_parens(NULL, NULL);

  /* Base */
  base = mpc_or(5, lit_str, lit_char, lit_regex, lit_id, parens);

  /* Factor = base + optional suffix */
  factor = mpc_and(2, mpcaf_grammar_repeat, base, factor_suffix, free);

  /* Term = factor + (factor)* */
  term_rest = mpc_many(mpcf_strfold, factor);
  term = mpc_and(2, mpcaf_grammar_and, factor, term_rest, free);

  /* Rule = term + ('|' term)* */
  rule_rest = mpc_many(mpcf_strfold, mpc_and(2, mpcf_snd_free, mpc_sym("|"), term, free));
  rule = mpc_and(2, mpcaf_grammar_or, term, rule_rest, free);

  /* Grammar = rule + (rule)* */
  rules = mpc_many(mpcf_strfold, rule);
  grammar_p = mpc_and(2, mpcf_snd_free, rules, mpc_pass(), free);

  /* We need to build the actual grammar parser. Since we cannot easily
     construct the full recursive grammar here without helper functions,
     we instead parse using a simpler approach: parse the grammar text
     with a hand-built parser. */

  /* Build the grammar parser properly */
  {
    mpc_parser_t *g_base, *g_factor, *g_term, *g_rule, *g_rules, *g_grammar;
    mpc_parser_t *g_parens, *g_braces, *g_brackets;
    mpc_parser_t *g_regex_flags, *g_regex_ci, *g_regex_ml, *g_regex_body;
    mpc_parser_t *g_count, *g_repeat_suffix, *g_factor_suffix;
    mpc_parser_t *g_lit_str, *g_lit_char, *g_lit_regex, *g_lit_id;
    mpc_parser_t *g_term_rest, *g_rule_rest;

    g_lit_str = mpc_apply_to(mpc_string_lit(), mpcaf_grammar_string, st);
    g_lit_char = mpc_apply_to(mpc_char_lit(), mpcaf_grammar_char, st);

    g_regex_ci = mpc_or(2, mpc_sym("i"), mpc_pass());
    g_regex_ml = mpc_or(2, mpc_sym("m"), mpc_pass());
    g_regex_flags = mpc_and(2, mpcf_strfold, g_regex_ci, g_regex_ml, free);

    g_regex_body = mpc_regex_lit();
    g_lit_regex = mpc_and(2, mpcaf_fold_regex, g_regex_body, mpc_maybe(g_regex_flags), free);

    g_lit_id = mpc_apply_to(mpc_ident(), mpcaf_grammar_id, st);

    g_count = mpc_tok_braces(mpc_int(), free);

    g_repeat_suffix = mpc_or(5,
      mpc_sym("*"),
      mpc_sym("+"),
      mpc_sym("?"),
      mpc_sym("!"),
      g_count);

    g_factor_suffix = mpc_maybe(g_repeat_suffix);

    g_parens = mpc_tok_parens(NULL, NULL);

    g_base = mpc_or(5, g_lit_str, g_lit_char, g_lit_regex, g_lit_id, g_parens);

    g_factor = mpc_and(2, mpcaf_grammar_repeat, g_base, g_factor_suffix, free);

    g_term_rest = mpc_many(mpcf_strfold, g_factor);
    g_term = mpc_and(2, mpcaf_grammar_and, g_factor, g_term_rest, free);

    g_rule_rest = mpc_many(mpcf_strfold, mpc_and(2, mpcf_snd_free, mpc_sym("|"), g_term, free));
    g_rule = mpc_and(2, mpcaf_grammar_or, g_term, g_rule_rest, free);

    g_rules = mpc_many(mpcf_strfold, g_rule);
    g_grammar = mpc_and(2, mpcf_snd_free, g_rules, mpc_pass(), free);

    /* Parse the grammar */
    if (!mpc_parse("<mpc_grammar>", grammar, g_grammar, &r)) {
      char *err = mpc_err_string(r.error);
      mpc_err_delete(r.error);
      p = mpc_failf("Invalid Grammar: %s", err);
      free(err);
      mpc_cleanup(1, g_grammar);
      return p;
    }

    p = (mpc_parser_t*)r.output;
    mpc_cleanup(1, g_grammar);
  }

  mpc_optimise(p);

  if (st->flags & MPCA_LANG_PREDICTIVE) {
    p = mpc_predictive(p);
  }

  return p;
}
