static mpc_err_t *mpca_lang_st(mpc_input_t *i, mpca_grammar_st_t *st) {
  mpc_result_t r;
  mpc_err_t *err;
  mpc_parser_t *p;
  mpc_parser_t *stmt;
  mpc_parser_t *expr;
  mpc_parser_t *term;
  mpc_parser_t *factor;
  mpc_parser_t *base;
  mpc_parser_t *repeats;
  mpc_parser_t *regex;
  mpc_parser_t *id;
  mpc_parser_t *lit;
  mpc_parser_t *chr;
  mpc_parser_t *num;
  mpc_parser_t *ws;

  ws = mpc_oneof(" \f\n\r\t\v");

  id = mpc_apply_to(mpc_tok(mpc_ident()), mpcaf_grammar_id, st);

  lit = mpc_apply_to(mpc_tok(mpc_string_lit()), mpcaf_grammar_string, st);

  chr = mpc_apply_to(mpc_tok(mpc_char_lit()), mpcaf_grammar_char, st);

  regex = mpc_apply_to(
    mpc_and(2, mpcf_snd_free,
      mpc_tok(mpc_regex_lit()),
      mpc_many(mpcf_strfold, mpc_oneof("ms"))),
    mpcaf_fold_regex, st);

  num = mpc_apply_to(
    mpc_tok(mpc_tok_braces(mpc_tok(mpc_int()), free)),
    mpcaf_grammar_id, st);

  base = mpc_or(5,
    lit,
    chr,
    regex,
    num,
    mpc_tok_parens(mpc_predictive(mpc_lift_val(NULL)), free));

  repeats = mpc_or(6,
    mpc_and(2, mpcf_snd_free, base, mpc_sym("*")),
    mpc_and(2, mpcf_snd_free, base, mpc_sym("+")),
    mpc_and(2, mpcf_snd_free, base, mpc_sym("?")),
    mpc_and(2, mpcf_snd_free, base, mpc_sym("!")),
    mpc_and(2, mpcf_snd_free, base, mpc_tok_brackets(mpc_tok(mpc_int()), free)),
    base);

  factor = mpc_many1(mpcaf_grammar_repeat, repeats);

  term = mpc_many1(mpcaf_grammar_and, factor);

  expr = mpc_many1(mpcaf_grammar_or,
    mpc_and(2, mpcf_snd_free, term, mpc_sym("|")));

  stmt = mpc_and(5, mpca_stmt_afold,
    mpc_tok(mpc_ident()),
    mpc_maybe(mpc_tok(mpc_string_lit())),
    mpc_sym(":"),
    expr,
    mpc_sym(";"));

  p = mpc_total(
    mpc_and(2, mpca_stmt_fold,
      mpc_many(mpca_stmt_list_apply_to, stmt),
      mpc_pass()),
    mpca_stmt_list_delete);

  mpc_optimise(p);

  if (!mpc_parse_input(i, p, &r)) {
    err = r.error;
    mpc_cleanup(1, p);
    return err;
  }

  mpc_cleanup(1, p);
  return NULL;
