static parson_bool_t is_valid_utf8(const char *string, size_t string_len)
{
    size_t pos = 0;

    while (pos < string_len) {
        int seq_len = 0;
        JSON_Status status;

        status = verify_utf8_sequence((const unsigned char *)(string + pos),
                                      string_len - pos, &seq_len);
        if (status != JSONSuccess) {
            return PARSON_FALSE;
        }
        if (seq_len <= 0) {
            return PARSON_FALSE;
        }
        pos += (size_t)seq_len;
    }

    return PARSON_TRUE;
}
