```c
static size_t json_object_get_cell_ix(const JSON_Object *object, const char *key, size_t key_len, unsigned long hash, parson_bool_t *out_found)
{
    size_t cell_ix;
    size_t probe;
    size_t cell_capacity;
    size_t *cells;
    unsigned long *hashes;
    char **names;
    size_t *cell_ixs;

    *out_found = PARSON_FALSE;

    cell_capacity = object->cell_capacity;
    cells = object->cells;
    hashes = object->hashes;
    names = object->names;
    cell_ixs = object->cell_ixs;

    cell_ix = (size_t)(hash & (unsigned long)(cell_capacity - 1));

    for (probe = 0; probe < cell_capacity; probe++) {
        size_t item_ix = cells[cell_ix];

        if (item_ix == OBJECT_INVALID_IX) {
            return cell_ix;
        }

        if (hashes[item_ix] == hash) {
            if (names[item_ix] != NULL && cell_ixs[item_ix] == cell_ix) {
                if (strlen(names[item_ix]) == key_len &&
                    memcmp(names[item_ix], key, key_len) == 0) {
                    *out_found = PARSON_TRUE;
                    return cell_ix;
                }
            }
        }

        cell_ix = (cell_ix + 1) & (cell_capacity - 1);
    }

    return OBJECT_INVALID_IX;
}
```

```c
static JSON_Status json_object_add(JSON_Object *object, char *name, JSON_Value *value)
{
    unsigned long hash;
    size_t key_len;
    size_t cell_ix;
    parson_bool_t found;

    if (object == NULL || name == NULL || value == NULL) {
        return JSONFailure;
    }

    key_len = strlen(name);
    hash = hash_string(name, key_len);
    found = PARSON_FALSE;
    cell_ix = json_object_get_cell_ix(object, name, key_len, hash, &found);
    if (found) {
        return JSONFailure;
    }

    if (object->count >= object->item_capacity) {
        JSON_Status status = json_object_grow_and_rehash(object);
        if (status != JSONSuccess) {
            return JSONFailure;
        }
        cell_ix = json_object_get_cell_ix(object, name, key_len, hash, &found);
    }

    object->names[object->count] = name;
    object->values[object->count] = value;
    object->cell_ixs[object->count] = cell_ix;
    object->hashes[object->count] = hash;
    object->cells[cell_ix] = object->count;
    object->count += 1;

    value->parent = json_object_get_wrapping_value(object);

    return JSONSuccess;
}
