static JSON_Status json_object_dotremove_internal(JSON_Object *object, const char *name, parson_bool_t free_value)
{
    const char *dot;
    JSON_Value *value;
    JSON_Object *nested;

    dot = strchr(name, '.');
    if (dot == NULL) {
        return json_object_remove_internal(object, name, free_value);
