    if (json_value_get_type(value) != JSONObject) {
        return JSONFailure;
    }

    nested = json_value_get_object(value);
    if (nested == NULL) {
        return JSONFailure;
    }

    return json_object_dotremove_internal(nested, dot + 1, free_value);
}
