static JSON_Status skip_quotes(const char **string)
{
    const char *p;

    p = *string;

    if (*p != '"') {
        return JSONFailure;
    }

    p++;

    while (*p != '\0') {
        if (*p == '\\') {
            p++;
            if (*p == '\0') {
                *string = p;
                return JSONFailure;
            }
            p++;
        } else if (*p == '"') {
            p++;
            *string = p;
            return JSONSuccess;
        } else {
            p++;
        }
    }

    *string = p;
    return JSONFailure;
}
