    if (string == NULL || *string == NULL || output_string_len == NULL) {
        return NULL;
    }

    start = *string;

    if (skip_quotes(string) != JSONSuccess) {
        return NULL;
    }

    end = *string;

    if (end <= start + 1) {
        return NULL;
    }

    input_len = (size_t)(end - start) - 2;

    result = process_string(start + 1, input_len, output_string_len);

    return result;
}
