static JSON_Value * parse_value(const char **string, size_t nesting)
{
    if (nesting > MAX_NESTING) {
        return NULL;
    }
    SKIP_WHITESPACES(string);
    switch (**string) {
        case '{':
            return parse_object_value(string, nesting + 1);
        case '[':
            return parse_array_value(string, nesting + 1);
        case '\"':
            return parse_string_value(string);
        case 'f':
        case 't':
            return parse_boolean_value(string);
        case '-':
        case '0':
        case '1':
        case '2':
        case '3':
        case '4':
        case '5':
        case '6':
        case '7':
        case '8':
        case '9':
            return parse_number_value(string);
        case 'n':
            return parse_null_value(string);
        default:
            return NULL;
    }
}
```

```c
static JSON_Value * parse_array_value(const char **string, size_t nesting)
{
    JSON_Value *array_value;
    JSON_Array *array;
    JSON_Value *new_value;

    array_value = json_value_init_array();
    if (array_value == NULL) {
        return NULL;
    }

    array = json_value_get_array(array_value);
    if (array == NULL) {
        json_value_free(array_value);
        return NULL;
    }

    if (**string != '[') {
        json_value_free(array_value);
        return NULL;
    }

    SKIP_CHAR(string);
    SKIP_WHITESPACES(string);

    if (**string == ']') {
        SKIP_CHAR(string);
        return array_value;
    }

    while (**string != '\0') {
        new_value = parse_value(string, nesting);
        if (new_value == NULL) {
            json_value_free(array_value);
            return NULL;
        }

        if (json_array_add(array, new_value) != JSONSuccess) {
            json_value_free(new_value);
            json_value_free(array_value);
            return NULL;
        }

        SKIP_WHITESPACES(string);

        if (**string != ',') {
            break;
        }

        SKIP_CHAR(string);
        SKIP_WHITESPACES(string);

        if (**string == ']') {
            break;
        }
    }

    SKIP_WHITESPACES(string);

    if (**string != ']') {
        json_value_free(array_value);
        return NULL;
    }

    if (json_array_resize(array, json_array_get_count(array)) != JSONSuccess) {
        json_value_free(array_value);
        return NULL;
    }

    SKIP_CHAR(string);
    return array_value;
}
