```c
JSON_Value * json_value_deep_copy(const JSON_Value *value)
{
    JSON_Value *copy = NULL;
    JSON_Value_Type type;
    size_t i, count;

    if (value == NULL) {
        return NULL;
    }

    type = json_value_get_type(value);
    if (type == JSONError) {
        return NULL;
    }

    switch (type) {
        case JSONArray: {
            JSON_Array *src_array = json_value_get_array(value);
            JSON_Array *dst_array;
            if (src_array == NULL) {
                return NULL;
            }
            copy = json_value_init_array();
            if (copy == NULL) {
                return NULL;
            }
            dst_array = json_value_get_array(copy);
            count = json_array_get_count(src_array);
            for (i = 0; i < count; i++) {
                JSON_Value *src_item = json_array_get_value(src_array, i);
                JSON_Value *item_copy = json_value_deep_copy(src_item);
                if (item_copy == NULL) {
                    json_value_free(copy);
                    return NULL;
                }
                if (json_array_add(dst_array, item_copy) != JSONSuccess) {
                    json_value_free(item_copy);
                    json_value_free(copy);
                    return NULL;
                }
            }
            return copy;
        }
        case JSONObject: {
            JSON_Object *src_object = json_value_get_object(value);
            JSON_Object *dst_object;
            if (src_object == NULL) {
                return NULL;
            }
            copy = json_value_init_object();
            if (copy == NULL) {
                return NULL;
            }
            dst_object = json_value_get_object(copy);
            count = json_object_get_count(src_object);
            for (i = 0; i < count; i++) {
                const char *name = json_object_get_name(src_object, i);
                JSON_Value *src_member = json_object_get_value(src_object, name);
                JSON_Value *member_copy;
                char *name_copy;
                if (name == NULL) {
                    json_value_free(copy);
                    return NULL;
                }
                member_copy = json_value_deep_copy(src_member);
                if (member_copy == NULL) {
                    json_value_free(copy);
                    return NULL;
                }
                name_copy = parson_strdup(name);
                if (name_copy == NULL) {
                    json_value_free(member_copy);
                    json_value_free(copy);
                    return NULL;
                }
                if (json_object_add(dst_object, name_copy, member_copy) != JSONSuccess) {
                    parson_free(name_copy);
                    json_value_free(member_copy);
                    json_value_free(copy);
                    return NULL;
                }
            }
            return copy;
        }
        case JSONString: {
            const JSON_String *str = json_value_get_string_desc(value);
            char *chars_copy;
            if (str == NULL) {
                return NULL;
            }
            chars_copy = parson_strndup(str->chars, str->length);
            if (chars_copy == NULL) {
                return NULL;
            }
            copy = json_value_init_string_no_copy(chars_copy, str->length);
            if (copy == NULL) {
                parson_free(chars_copy);
                return NULL;
            }
            return copy;
        }
        case JSONNumber:
            return json_value_init_number(json_value_get_number(value));
        case JSONBoolean:
            return json_value_init_boolean(json_value_get_boolean(value));
        case JSONNull:
            return json_value_init_null();
        default:
            return NULL;
    }
}
```

