JSON_Status json_object_set_value(JSON_Object *object, const char *name, JSON_Value *value)
{
    size_t i;
    size_t key_len;
    unsigned long hash;
    parson_bool_t found;
    size_t cell_ix;
    char *name_copy;
    JSON_Value *old_value;

    if (object == NULL || name == NULL || value == NULL) {
        return JSONFailure;
    }
    if (value->parent != NULL) {
        return JSONFailure;
    }

    key_len = strlen(name);
    hash = hash_string(name, key_len);
    found = PARSON_FALSE;
    cell_ix = json_object_get_cell_ix(object, name, key_len, hash, &found);

    if (found) {
        i = object->cell_ixs[cell_ix];
        old_value = object->values[i];
        json_value_free(old_value);
        object->values[i] = value;
        value->parent = json_object_get_wrapping_value(object);
        return JSONSuccess;
    }

    if (object->count >= object->item_capacity) {
        if (json_object_grow_and_rehash(object) != JSONSuccess) {
            return JSONFailure;
        }
        cell_ix = json_object_get_cell_ix(object, name, key_len, hash, &found);
    }

    name_copy = parson_strdup(name);
    if (name_copy == NULL) {
        return JSONFailure;
    }

    i = object->count;
    object->names[i] = name_copy;
    object->values[i] = value;
    object->hashes[i] = hash;
    object->cell_ixs[i] = cell_ix;
    object->cells[cell_ix] = i;
    object->count = i + 1;
    value->parent = json_object_get_wrapping_value(object);

    return JSONSuccess;
}
