JSON_Status json_validate(const JSON_Value *schema, const JSON_Value *value)
{
    JSON_Value_Type schema_type;
    JSON_Value_Type value_type;

    if (schema == NULL || value == NULL) {
        return JSONFailure;
    }

    schema_type = json_value_get_type(schema);
    value_type = json_value_get_type(value);

    if (schema_type != JSONNull && schema_type != value_type) {
        return JSONFailure;
    }

    if (schema_type == JSONArray) {
        JSON_Array *schema_array = json_value_get_array(schema);
        JSON_Array *value_array = json_value_get_array(value);
        size_t schema_count;
        size_t value_count;
        size_t i;
        JSON_Value *item_schema;

        if (schema_array == NULL || value_array == NULL) {
            return JSONFailure;
        }

        schema_count = json_array_get_count(schema_array);
        if (schema_count == 0) {
            return JSONSuccess;
        }

        item_schema = json_array_get_value(schema_array, 0);
        value_count = json_array_get_count(value_array);

        for (i = 0; i < value_count; i++) {
            JSON_Value *item = json_array_get_value(value_array, i);
            if (json_validate(item_schema, item) != JSONSuccess) {
                return JSONFailure;
            }
        }

        return JSONSuccess;
    }

    if (schema_type == JSONObject) {
        JSON_Object *schema_object = json_value_get_object(schema);
        JSON_Object *value_object = json_value_get_object(value);
        size_t schema_count;
        size_t value_count;
        size_t i;

        if (schema_object == NULL || value_object == NULL) {
            return JSONFailure;
        }

        schema_count = json_object_get_count(schema_object);
        if (schema_count == 0) {
            return JSONSuccess;
        }

        value_count = json_object_get_count(value_object);
        if (value_count < schema_count) {
            return JSONFailure;
        }

        for (i = 0; i < schema_count; i++) {
            const char *name = json_object_get_name(schema_object, i);
            JSON_Value *member_schema;
            JSON_Value *member_value;

            if (name == NULL) {
                return JSONFailure;
            }

            member_schema = json_object_get_value(schema_object, name);
            member_value = json_object_get_value(value_object, name);

            if (member_value == NULL) {
                return JSONFailure;
            }

            if (json_validate(member_schema, member_value) != JSONSuccess) {
                return JSONFailure;
            }
        }

        return JSONSuccess;
    }

    return JSONSuccess;
}
