int json_value_equals(const JSON_Value *a, const JSON_Value *b)
{
    JSON_Value_Type type_a;
    JSON_Value_Type type_b;

    type_a = json_value_get_type(a);
    type_b = json_value_get_type(b);

    if (type_a != type_b) {
        return 0;
    }

    switch (type_a) {
        case JSONArray: {
            JSON_Array *arr_a;
            JSON_Array *arr_b;
            size_t count;
            size_t i;

            arr_a = json_value_get_array(a);
            arr_b = json_value_get_array(b);
            count = json_array_get_count(arr_a);
            if (count != json_array_get_count(arr_b)) {
                return 0;
            }
            for (i = 0; i < count; i++) {
                if (!json_value_equals(json_array_get_value(arr_a, i),
                                       json_array_get_value(arr_b, i))) {
                    return 0;
                }
            }
            return 1;
        }

        case JSONObject: {
            JSON_Object *obj_a;
            JSON_Object *obj_b;
            size_t count;
            size_t i;

            obj_a = json_value_get_object(a);
            obj_b = json_value_get_object(b);
            count = json_object_get_count(obj_a);
            if (count != json_object_get_count(obj_b)) {
                return 0;
            }
            for (i = 0; i < count; i++) {
                const char *name;
                JSON_Value *val_a;
                JSON_Value *val_b;

                name = json_object_get_name(obj_a, i);
                val_a = json_object_get_value(obj_a, name);
                val_b = json_object_get_value(obj_b, name);
                if (val_b == NULL) {
                    return 0;
                }
                if (!json_value_equals(val_a, val_b)) {
                    return 0;
                }
            }
            return 1;
        }

        case JSONString: {
            const JSON_String *str_a;
            const JSON_String *str_b;

            str_a = json_value_get_string_desc(a);
            str_b = json_value_get_string_desc(b);
            if (str_a == NULL || str_b == NULL) {
                return 0;
            }
            if (str_a->length != str_b->length) {
                return 0;
            }
            if (str_a->length == 0) {
                return 1;
            }
            if (memcmp(str_a->chars, str_b->chars, str_a->length) == 0) {
                return 1;
            }
            return 0;
        }

        case JSONBoolean:
            return json_value_get_boolean(a) == json_value_get_boolean(b);

        case JSONNumber:
            return fabs(json_value_get_number(a) - json_value_get_number(b)) < 0.000001;

        case JSONError:
        case JSONNull:
            return 1;

        default:
            return 1;
    }
}
