static double ncr(double n, double r)
{
    if (!(n >= 0.0) || !(r >= 0.0))
        return NAN;
    if (n < r)
        return NAN;
    if (n > 4294967295.0 || r > 4294967295.0)
        return INFINITY;

    unsigned long long int nn = (unsigned long long int)n;
    unsigned long long int rr = (unsigned long long int)r;

    if (rr > nn - rr)
        rr = nn - rr;

    unsigned long long int result = 1;
    unsigned long long int i;

    for (i = 1; i <= rr; i++) {
        unsigned long long int num = nn - rr + i;
        unsigned long long int den = i;

        unsigned long long int g = gcd(num, den);
        num /= g;
        den /= g;

        g = gcd(result, den);
        result /= g;
        den /= g;

        if (den != 1) {
            /* Should not happen after full reduction, but guard anyway. */
            if (result > ULLONG_MAX / num)
                return INFINITY;
            result *= num;
            result /= den;
        } else {
            if (result > ULLONG_MAX / num)
                return INFINITY;
            result *= num;
        }
    }

    return (double)result;
}
