static const te_variable *find_builtin(const char *name, int len)
{
    int imin = 0;
    int imax = (int)(sizeof(functions) / sizeof(functions[0])) - 1;

    while (imax >= imin) {
        int i = (imin + imax) / 2;
        int c = strncmp(name, functions[i].name, (size_t)len);
        if (c == 0) {
            c = '\0' - functions[i].name[len];
        }
        if (c == 0) {
            return &functions[i];
        } else if (c < 0) {
            imax = i - 1;
        } else {
            imin = i + 1;
        }
    }

    return NULL;
}
