static const te_variable *find_lookup(const state *s, const char *name, int len)
{
    int i;
    const te_variable *var;

    if (s == NULL || s->lookup == NULL || s->lookup_len <= 0 || name == NULL || len < 0)
        return NULL;

    for (i = 0; i < s->lookup_len; i++) {
        var = &s->lookup[i];
        if (var->name == NULL)
            continue;
        if (strncmp(var->name, name, (size_t)len) == 0 && var->name[len] == '\0')
            return var;
    }

    return NULL;
}
