static double parse_number(state *s)
{
    const char *p = s->next;
    double value = 0.0;

    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X') && isxdigit((unsigned char)p[2])) {
        unsigned long long ival = 0;
        p += 2;
        while (isxdigit((unsigned char)*p)) {
            int d;
            if (*p >= '0' && *p <= '9') d = *p - '0';
            else if (*p >= 'a' && *p <= 'f') d = *p - 'a' + 10;
            else d = *p - 'A' + 10;
            ival = ival * 16u + (unsigned long long)d;
            p++;
        }
        value = (double)ival;
        s->next = p;
        s->type = TOK_NUMBER;
        return value;
    }

    {
        const char *start = p;
        int digits = 0;
        double intpart = 0.0;
        double fracpart = 0.0;
        double fracscale = 1.0;
        int expval = 0;
        int expsign = 1;
        int has_exp = 0;

        while (*p >= '0' && *p <= '9') {
            intpart = intpart * 10.0 + (double)(*p - '0');
            p++;
            digits++;
        }

        if (*p == '.') {
            const char *dot = p;
            p++;
            while (*p >= '0' && *p <= '9') {
                fracpart = fracpart * 10.0 + (double)(*p - '0');
                fracscale *= 10.0;
                p++;
                digits++;
            }
            if (digits == 0) {
                (void)dot;
                s->type = TOK_ERROR;
                return 0.0;
            }
        }

        if (digits == 0) {
            s->type = TOK_ERROR;
            return 0.0;
        }

        if (*p == 'e' || *p == 'E') {
            const char *emark = p;
            const char *q = p + 1;
            int esign = 1;
            int edigits = 0;
            int eval = 0;
            if (*q == '+' || *q == '-') {
                if (*q == '-') esign = -1;
                q++;
            }
            while (*q >= '0' && *q <= '9') {
                if (eval < 100000) eval = eval * 10 + (*q - '0');
                q++;
                edigits++;
            }
            if (edigits > 0) {
                has_exp = 1;
                expval = eval;
                expsign = esign;
                p = q;
            } else {
                p = emark;
            }
        }

        value = intpart + fracpart / fracscale;

        if (has_exp && expval != 0) {
            int e = expval * expsign;
            if (e > 0) {
                while (e > 0) {
                    int step = e > 22 ? 22 : e;
                    value *= exact_pow10[step];
                    e -= step;
                }
            } else {
                e = -e;
                while (e > 0) {
                    int step = e > 22 ? 22 : e;
                    value /= exact_pow10[step];
                    e -= step;
                }
            }
        }

        (void)start;
        s->next = p;
        s->type = TOK_NUMBER;
        return value;
    }
}
