te_expr *te_compile(const char *expression, const te_variable *variables, int var_count, int *error)
{
    state s;
    te_expr *root;
    int status;

    s.next = expression;
    s.lookup = variables;
    s.lookup_len = var_count;
    s.applied_unary = 0;
    s.depth = 0;

    next_token(&s);
    root = binary(&s, PREC_NONE);

    if (root && s.type != TOK_END) {
        te_free(root);
        root = NULL;
    }

    if (root) {
        optimize(root);
        if (error)
            *error = 0;
    } else {
        if (error) {
            if (s.type == TOK_ERROR) {
                status = (int)(s.next - expression);
                if (status == 0)
                    status = 1;
                *error = status;
            } else {
                *error = -1;
            }
        }
    }

    return root;
}
